service.method:
/* SepoaReqSealManager.doSelectSSIAD */ SELECT SIAD.HOUSE_CODE , SIAD.COMPANY_CODE , SIAD.ROW_NUM , SIAD.SMR_NUMBER , SIAD.SMR_STATUS , SIAD.ADD_DATE , SIAD.ADD_TIME , SIAD.ADD_USER_ID , SIAD.CHANGE_DATE , SIAD.CHANGE_TIME , SIAD.CHANGE_USER_ID , SIAD.DEL_FLAG , SIAD.APPLY_TYPE , SIAD.SUBJECT , SIAD.RE_FLAG , SIAD.RE_DETAIL , SIAD.REQ_SEAL_USE_TYPE , SIAD.REQ_SEAL_USE_TYPE AS SEAL_USE_TYPE , SIAD.REQ_SEAL_USE_TYPE AS SEAL_USE_TYPE_CODE , ( SELECT SUBJECT FROM SUDGL WHERE HOUSE_CODE = SIAD.HOUSE_CODE AND COMPANY_CODE = SIAD.COMPANY_CODE AND USE_NUMBER = SIAD.REQ_SEAL_USE_TYPE AND #DB_OWNER#NVL(DEL_FLAG,'N') = 'N' ) AS SEAL_USE_TYPE_TEXT , SIAD.SUBMISSION_PLACE , SIAD.REMARK , SIAD.EXPLANATION , SIAD.RCPT_TYPE , SIAD.RCPT_REMARK , SIAD.CONFIRM_DATE , SIAD.CONFIRM_TIME , SIAD.CONFIRM_USER_ID , SIAD.SUBMIT_TYPE , SIAD.SUBMIT_REMARK , SIAD.LEGAL_WATERMARK , CASE ${session.LANGUAGE} WHEN 'KO' THEN ADD_USER_USMT.USER_NAME_LOC ELSE ADD_USER_USMT.USER_NAME_ENG END AS ADD_USER_NAME , CASE ${session.LANGUAGE} WHEN 'KO' THEN ADD_USER_DEPT.DEPT_NAME_LOC ELSE ADD_USER_DEPT.DEPT_NAME_ENG END AS DEPT_NAME , #DB_OWNER#GETUSERNAME(SIAD.HOUSE_CODE, SIAD.COMPANY_CODE, SIAD.CONFIRM_USER_ID, ${session.LANGUAGE}) as CONFIRM_USER_NAME , SIAD.REJECT_REASON AS ACCEPT_REASON , CONCAT(' ', ( SELECT -- REPLACE(WM_CONCAT(DISTINCT SEAL.SUBJECT),',',', ') AS SUBJECT -- 10g , 11g LISTAGG(SEAL.SUBJECT, ', ') WITHIN GROUP(ORDER BY SEAL.SUBJECT) AS SUBJECT -- 11g 이상 FROM SSIPD_SEAL PD_SEAL JOIN SSEAL SEAL ON SEAL.HOUSE_CODE = PD_SEAL.HOUSE_CODE AND SEAL.COMPANY_CODE = PD_SEAL.COMPANY_CODE AND SEAL.MANAGE_NUMBER = PD_SEAL.MANAGE_NUMBER WHERE PD_SEAL.HOUSE_CODE = SIAD.HOUSE_CODE AND PD_SEAL.COMPANY_CODE = SIAD.COMPANY_CODE AND PD_SEAL.SMR_NUMBER = SIAD.SMR_NUMBER )) AS SEAL_NAMES , CONCAT(' ', ( SELECT -- REPLACE(WM_CONCAT(DISTINCT PD_SEAL.MANAGE_NUMBER ),',',', ') AS MANAGE_NUMBER -- 10 g , 11 g LISTAGG(PD_SEAL.MANAGE_NUMBER,', ') WITHIN GROUP(ORDER BY PD_SEAL.MANAGE_NUMBER) AS MANAGE_NUMBER -- 11g 이상 -- GROUP_CONCAT(PD_SEAL.MANAGE_NUMBER SEPARATOR ', ') -- MySQL FROM SSIPD_SEAL PD_SEAL WHERE PD_SEAL.HOUSE_CODE = SIAD.HOUSE_CODE AND PD_SEAL.COMPANY_CODE = SIAD.COMPANY_CODE AND PD_SEAL.SMR_NUMBER = SIAD.SMR_NUMBER )) AS MANAGE_NUMBERS , CONCAT(' ', ( SELECT -- REPLACE(WM_CONCAT(DISTINCT SEAL.SEAL_CATEGORY ),',',', ') AS SEAL_CATEGORY -- 10 g , 11 g LISTAGG(SEAL.SEAL_CATEGORY,', ') WITHIN GROUP(ORDER BY SEAL.SEAL_CATEGORY) AS SEAL_CATEGORY -- 11g 이상 -- GROUP_CONCAT(SEAL.SEAL_CATEGORY SEPARATOR ', ') FROM SSIPD_SEAL PD_SEAL JOIN SSEAL SEAL ON SEAL.HOUSE_CODE = PD_SEAL.HOUSE_CODE AND SEAL.COMPANY_CODE = PD_SEAL.COMPANY_CODE AND SEAL.MANAGE_NUMBER = PD_SEAL.MANAGE_NUMBER WHERE PD_SEAL.HOUSE_CODE = SIAD.HOUSE_CODE AND PD_SEAL.COMPANY_CODE = SIAD.COMPANY_CODE AND PD_SEAL.SMR_NUMBER = SIAD.SMR_NUMBER )) AS SEAL_CATEGORY_CODES , CASE WHEN REQ_SEAL_CNT > REQ_SEAL_REAL_DOC_CNT THEN 'N' ELSE 'Y' END REQ_SEAL_REAL_YN
, CASE WHEN SIAD.RE_FLAG != 'R' OR SIAD.SMR_STATUS != 'C' THEN 'I' WHEN RA.DOC_NO_MIN = '' THEN 'N' ELSE 'D' END AS REAL_ATTACH_STATUS
FROM SSIAD SIAD LEFT JOIN SUSMT ADD_USER_USMT ON ADD_USER_USMT.HOUSE_CODE = SIAD.HOUSE_CODE AND ADD_USER_USMT.USER_ID = SIAD.ADD_USER_ID LEFT JOIN SDEPT ADD_USER_DEPT ON ADD_USER_DEPT.HOUSE_CODE = ADD_USER_USMT.HOUSE_CODE AND ADD_USER_DEPT.COMPANY_CODE = ADD_USER_USMT.COMPANY_CODE AND ADD_USER_DEPT.DEPT = SIAD.ADD_USER_DEPT LEFT OUTER JOIN (SELECT SUX_WKEY1 , HOUSE_CODE , COMPANY_CODE , DEL_FLAG, APP_NO , APP_NO_SEQ , CURRENT_STAGE FROM SGWGL WHERE APP_NO = (SELECT MAX(APP_NO) FROM SGWGL) )GWGL ON GWGL.HOUSE_CODE = SIAD.HOUSE_CODE AND GWGL.COMPANY_CODE =SIAD.COMPANY_CODE AND GWGL.SUX_WKEY1 = SIAD.SMR_NUMBER AND NVL(GWGL.DEL_FLAG,'N') = 'N' LEFT OUTER JOIN SGWLN GWLN ON GWLN.HOUSE_CODE = GWGL.HOUSE_CODE AND GWLN.COMPANY_CODE = GWGL.COMPANY_CODE AND GWLN.APP_NO = GWGL.APP_NO AND GWLN.APP_NO_SEQ = GWGL.APP_NO_SEQ AND GWLN.APP_STAGE = GWGL.CURRENT_STAGE LEFT OUTER JOIN ( SELECT SIPD.HOUSE_CODE , SIPD.COMPANY_CODE , SIPD.SMR_NUMBER , COUNT(REQ_SEAL_CNT) REQ_SEAL_CNT , COUNT(REQ_SEAL_REAL_DOC_CNT) REQ_SEAL_REAL_DOC_CNT FROM ( SELECT CASE WHEN LAYER = 'REQ_SEAL' THEN 1 END REQ_SEAL_CNT , CASE WHEN LAYER = 'REQ_SEAL_REAL_DOC' THEN 1 END REQ_SEAL_REAL_DOC_CNT , SIPD.HOUSE_CODE, SIPD.COMPANY_CODE, SIPD.SMR_NUMBER, LAYER FROM SFMFI FI JOIN SSIPD SIPD ON FI.HOUSE_CODE = SIPD.HOUSE_CODE AND FI.COMPANY_CODE = SIPD.COMPANY_CODE AND FI.DOC_NUMBER = SIPD.SMR_NUMBER || '_' || SIPD.SMD_NUMBER AND NVL(SIPD.DEL_FLAG, 'N') = 'N' WHERE FI.HOUSE_CODE = ${session.HOUSE_CODE} AND FI.COMPANY_CODE = ${session.COMPANY_CODE} ) SIPD GROUP BY SIPD.HOUSE_CODE, SIPD.COMPANY_CODE, SIPD.SMR_NUMBER) RRDOC ON RRDOC.HOUSE_CODE = SIAD.HOUSE_CODE AND RRDOC.COMPANY_CODE = SIAD.COMPANY_CODE AND RRDOC.SMR_NUMBER = SIAD.SMR_NUMBER
LEFT JOIN ( SELECT SIPD.HOUSE_CODE, SIPD.COMPANY_CODE, SIPD.SMR_NUMBER, MIN(NVL(SFILE.DOC_NO,'')) AS DOC_NO_MIN FROM SSIPD SIPD LEFT JOIN SFILE ON SFILE.HOUSE_CODE = SIPD.HOUSE_CODE AND SFILE.DOC_NO = SIPD.SMD_NUMBER AND NVL(SFILE.DEL_FLAG, 'N') = 'N' GROUP BY SIPD.HOUSE_CODE, SIPD.COMPANY_CODE, SIPD.SMR_NUMBER ) RA ON RA.HOUSE_CODE = SIAD.HOUSE_CODE AND RA.COMPANY_CODE = SIAD.COMPANY_CODE AND RA.SMR_NUMBER = SIAD.SMR_NUMBER
WHERE SIAD.HOUSE_CODE = ${session.HOUSE_CODE} AND SIAD.SMR_NUMBER = $S{SMR_NUMBER} AND SIAD.ADD_USER_ID = $S{REQ_USER_ID}
AND SIAD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SIAD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SIAD.COMPANY_CODE = $S{COMPANY_CODE} AND SIAD.COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})
AND ( SIAD.ADD_USER_ID = ${session.ID} OR ( ADD_USER_DEPT.DEPT = ${session.DEPARTMENT} AND SIAD.SMR_STATUS != 'T' ) )
AND SIAD.APPLY_TYPE IN($INS{APPLY_TYPE}) AND SIAD.RE_FLAG = $S{RE_FLAG} AND SIAD.SMR_STATUS IN($INS{SMR_STATUS}) AND (SIAD.SUBJECT LIKE '%' || $S{F_KEYWORD} || '%' OR SIAD.ADD_USER_ID LIKE '%' || $S{F_KEYWORD} || '%' OR SIAD.SMR_NUMBER LIKE '%' || $S{F_KEYWORD} || '%' OR SIAD.SUBMISSION_PLACE LIKE '%' || $S{F_KEYWORD} || '%' OR ADD_USER_USMT.USER_NAME_LOC LIKE '%' || $S{F_KEYWORD} || '%') AND SIAD.REQ_SEAL_USE_TYPE = $S{REQ_SEAL_USE_TYPE} AND SIAD.ADD_DATE >= $S{F_CALENDAR_FROM} AND SIAD.ADD_DATE <= $S{F_CALENDAR_TO} AND #DB_OWNER#NVL(SIAD.DEL_FLAG,'N') = 'N'
AND EXISTS (SELECT PDSEAL.SMR_NUMBER FROM SSIPD_SEAL PDSEAL LEFT JOIN SMAND MAND ON MAND.HOUSE_CODE = PDSEAL.HOUSE_CODE AND MAND.COMPANY_CODE = PDSEAL.COMPANY_CODE AND MAND.MAND_TYPE = '01' AND MAND.GIVE_USER_ID = PDSEAL.MANAGER_ID AND ${current.DATE} BETWEEN START_DATE AND END_DATE WHERE PDSEAL.HOUSE_CODE = SIAD.HOUSE_CODE AND PDSEAL.COMPANY_CODE = SIAD.COMPANY_CODE AND PDSEAL.SMR_NUMBER = SIAD.SMR_NUMBER AND (PDSEAL.MANAGER_ID = ${session.ID} OR MAND.RECE_USER_ID = ${session.ID}) AND PDSEAL.ACCEPT_FLAG = $S{ACCEPT_FLAG} )
AND EXISTS ( SELECT SEAL.SEAL_CATEGORY FROM SSIPD_SEAL PD_SEAL JOIN SSEAL SEAL ON SEAL.HOUSE_CODE = PD_SEAL.HOUSE_CODE AND SEAL.COMPANY_CODE = PD_SEAL.COMPANY_CODE AND SEAL.MANAGE_NUMBER = PD_SEAL.MANAGE_NUMBER WHERE PD_SEAL.HOUSE_CODE = SIAD.HOUSE_CODE AND PD_SEAL.COMPANY_CODE = SIAD.COMPANY_CODE AND PD_SEAL.SMR_NUMBER = SIAD.SMR_NUMBER AND SEAL.SEAL_CATEGORY IN($IN{F_SEAL_CATEGORY}) )
ORDER BY ADD_DATE DESC, ADD_TIME DESC, SIAD.SMR_NUMBER DESC


INSERT INTO SSIAD(
	  HOUSE_CODE
	, COMPANY_CODE
	, SMR_NUMBER
	, SMR_STATUS
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, DEL_FLAG
	, APPLY_TYPE
	, SUBJECT
	, RE_FLAG
	, RE_DETAIL
	, REQ_SEAL_USE_TYPE
	, SUBMISSION_PLACE
	, EXPLANATION
	, REMARK
	, RCPT_TYPE
	, RCPT_REMARK
	, SUBMIT_TYPE
	, SUBMIT_REMARK
	, LEGAL_WATERMARK
	, SOURCE_NO
	, ADD_USER_DEPT
	, ROW_NUM
) VALUES (
	  ${session.HOUSE_CODE  }
	, ${session.COMPANY_CODE}
	, ${SMR_NUMBER          }
	, ${SMR_STATUS          }
	, ${current.DATE        }
	, ${current.TIME        }
	, ${session.ID          }
	, 'N'
	, ${APPLY_TYPE          }
	, ${SUBJECT             }
	, ${RE_FLAG             }
	, ${RE_DETAIL           }
	, ${REQ_SEAL_USE_TYPE   }
	, ${SUBMISSION_PLACE    }
	, ${EXPLANATION}
	, ${REMARK              }
	, ${RCPT_TYPE           }
	, ${RCPT_REMARK         }
	, ${SUBMIT_TYPE         }
	, ${SUBMIT_REMARK       }
	, ${LEGAL_WATERMARK     }
	, ${SOURCE_NO			}
	, ${session.DEPARTMENT	}
	,
	   CASE
	          WHEN ${APPLY_TYPE} IN ('U', 'C') THEN (
	              SELECT TO_CHAR(MAX(TO_NUMBER(ROW_NUM)) + 1)
	              FROM SSIAD
	              WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	              AND COMPANY_CODE = ${session.COMPANY_CODE}
	              AND APPLY_TYPE IN ('U', 'C')
	          )
	          WHEN ${APPLY_TYPE} = 'D' THEN (
	              SELECT TO_CHAR(MAX(TO_NUMBER(ROW_NUM)) + 1)
	              FROM SSIAD
	              WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	              AND COMPANY_CODE = ${session.COMPANY_CODE}
	              AND APPLY_TYPE = 'D'
	          )
		END
)


UPDATE
	SSIAD
SET
	DEL_FLAG = 'Y'
	, CHANGE_DATE       = ${current.DATE}
	, CHANGE_TIME       = ${current.TIME}
	, CHANGE_USER_ID    = ${session.ID}
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}

/* SepoaReqSealManager.doSelectSSIPD */ SELECT SIPD.HOUSE_CODE , SIPD.COMPANY_CODE , SIPD.SMR_NUMBER , SIPD.SMD_NUMBER , SIPD.ADD_DATE , SIPD.ADD_TIME , SIPD.ADD_USER_ID , SIPD.CHANGE_DATE , SIPD.CHANGE_TIME , SIPD.CHANGE_USER_ID , SIPD.DEL_FLAG , SIPD.SEAL_TYPE , SIPD.SEAL_MG_DEPT , SIPD.SUBJECT , SIPD.COUNT , SIPD.PRINT_COUNT , SIPD.DOWN_COUNT , SIPD.REAL_ATTACH_NO , SIAD.SMR_STATUS , ( SELECT COUNT(1) FROM SFILE A WHERE A.HOUSE_CODE = ${session.HOUSE_CODE} AND A.DOC_NO = SIPD.SMD_NUMBER AND NVL(A.DEL_FLAG, 'N') <> 'Y' ) AS REAL_ATTACH_CNT , ( SELECT COUNT(*) FROM SFILE A WHERE A.HOUSE_CODE = ${session.HOUSE_CODE} AND A.DOC_NO = SIPD.OTHER_FILE_NO AND NVL(A.DEL_FLAG, 'N') <> 'Y' ) AS OTHER_FILE_CNT , SIPD.ITEMS_JSON , SIPD.MARK_COUNT , SIPD.RE_DETAIL , SIAD.RE_FLAG , SIPD.OTHER_FILE_NO , SIPD.PUBLISH_NO FROM SSIPD SIPD LEFT OUTER JOIN SSIAD SIAD ON SIAD.HOUSE_CODE = SIPD.HOUSE_CODE AND SIAD.COMPANY_CODE = SIPD.COMPANY_CODE AND SIAD.SMR_NUMBER = SIPD.SMR_NUMBER WHERE SIPD.HOUSE_CODE = ${session.HOUSE_CODE} AND SIPD.SMR_NUMBER = ${SMR_NUMBER} AND SIPD.SMD_NUMBER = $S{SMD_NUMBER}
AND SIPD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SIPD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SIPD.COMPANY_CODE = $S{COMPANY_CODE}

/* SepoaReqSealManager.doSelectSSIPD */ SELECT SIPD.HOUSE_CODE , SIPD.COMPANY_CODE , SIPD.SMR_NUMBER , SIPD.SMD_NUMBER , SIPD.ADD_DATE , SIPD.ADD_TIME , SIPD.ADD_USER_ID , SIPD.CHANGE_DATE , SIPD.CHANGE_TIME , SIPD.CHANGE_USER_ID , SIPD.DEL_FLAG , SIPD.SEAL_TYPE , SIPD.SEAL_MG_DEPT , SIPD.SUBJECT , SIPD.COUNT , SIPD.PRINT_COUNT , SIPD.DOWN_COUNT , SIPD.REAL_ATTACH_NO , SIAD.SMR_STATUS , GETUSERNAME(SIPD.HOUSE_CODE, SIPD.COMPANY_CODE, SIPD.ADD_USER_ID, ${session.LANGUAGE}) as USER_NAME , GETUSEREMAIL(SIPD.HOUSE_CODE, SIPD.COMPANY_CODE, SIPD.ADD_USER_ID, ${session.LANGUAGE}) as USER_EMAIL , ( SELECT COUNT(1) FROM SFILE A WHERE A.HOUSE_CODE = ${session.HOUSE_CODE} AND A.DOC_NO = SIPD.SMD_NUMBER AND NVL(A.DEL_FLAG, 'N') <> 'Y' ) AS REAL_ATTACH_CNT , ( SELECT COUNT(*) FROM SFILE A WHERE A.HOUSE_CODE = ${session.HOUSE_CODE} AND A.DOC_NO = SIPD.OTHER_FILE_NO AND NVL(A.DEL_FLAG, 'N') <> 'Y' ) AS OTHER_FILE_CNT , SIPD.ITEMS_JSON , SIPD.MARK_COUNT , SIPD.RE_DETAIL , SIAD.RE_FLAG , SIPD.OTHER_FILE_NO , SIPD.PUBLISH_NO FROM SSIPD SIPD LEFT OUTER JOIN SSIAD SIAD ON SIAD.HOUSE_CODE = SIPD.HOUSE_CODE AND SIAD.COMPANY_CODE = SIPD.COMPANY_CODE AND SIAD.SMR_NUMBER = SIPD.SMR_NUMBER WHERE SIPD.HOUSE_CODE = ${session.HOUSE_CODE} AND SIPD.SMR_NUMBER = ${SMR_NUMBER} AND SIPD.SMD_NUMBER = $S{SMD_NUMBER}
AND SIPD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SIPD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SIPD.COMPANY_CODE = $S{COMPANY_CODE}


INSERT INTO SSIPD (
	  HOUSE_CODE
	, COMPANY_CODE
	, SMR_NUMBER
	, SMD_NUMBER
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, DEL_FLAG
	, SEAL_TYPE
	, SEAL_MG_DEPT
	, SUBJECT
	, COUNT
	, ITEMS_JSON
	, MARK_COUNT
	, RE_DETAIL
	, OTHER_FILE_NO
) VALUES (
	  ${session.HOUSE_CODE  }
	, ${session.COMPANY_CODE}
	, ${SMR_NUMBER          }
	, ${SMD_NUMBER          }
	, ${current.DATE        }
	, ${current.TIME        }
	, ${session.ID          }
	, 'N'
	, ${SEAL_TYPE           }
	, ${SEAL_MG_DEPT        }
	, ${SUBJECT             }
	, ${COUNT               }
	, ${ITEMS_JSON			}
	, ${MARK_COUNT			}
	, ${RE_DETAIL			}
	, ${OTHER_FILE_NO		}
)


UPDATE SSIPD SET
	  CHANGE_DATE    	= ${current.DATE}
	, CHANGE_TIME    	= ${current.TIME}
	, CHANGE_USER_ID 	= ${session.ID}
	, DEL_FLAG       	= NVL(${DEL_FLAG    }        , DEL_FLAG    )
	, SEAL_TYPE      	= NVL(${SEAL_TYPE   }        , SEAL_TYPE   )
	, SEAL_MG_DEPT   	= NVL(${SEAL_MG_DEPT}        , SEAL_MG_DEPT)
	, SUBJECT        	= NVL(${SUBJECT     }        , SUBJECT     )
	, COUNT          	= NVL(${COUNT       }        , COUNT       )
	, PRINT_COUNT    	= NVL(${PRINT_COUNT }        , PRINT_COUNT )
	, DOWN_COUNT     	= NVL(${DOWN_COUNT  }        , DOWN_COUNT  )
	, REAL_ATTACH_NO	= NVL(${REAL_ATTACH_NO }     , REAL_ATTACH_NO )
	, ITEMS_JSON		= NVL(${ITEMS_JSON  }        , ITEMS_JSON  )
	, MARK_COUNT		= NVL(${MARK_COUNT  }        , MARK_COUNT  )
	, RE_DETAIL			= NVL(${RE_DETAIL   }        , RE_DETAIL   )
	, OTHER_FILE_NO		= NVL(${OTHER_FILE_NO}       , OTHER_FILE_NO )
	, ACCESS_LINK 	    = NVL(${ACCESS_LINK}, ACCESS_LINK)
WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
AND COMPANY_CODE 	= ${session.COMPANY_CODE}
AND SMR_NUMBER 		= ${SMR_NUMBER}
AND SMD_NUMBER 		= ${SMD_NUMBER}


DELETE FROM SSIPD
WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
AND COMPANY_CODE 	= ${session.COMPANY_CODE}
AND SMR_NUMBER 		= ${SMR_NUMBER}
AND SMD_NUMBER 		= ${SMD_NUMBER}

/* SepoaReqSealManager.doSelectSSIPD_SEAL */ SELECT PDSE.HOUSE_CODE , PDSE.COMPANY_CODE , PDSE.SMR_NUMBER , PDSE.SMD_NUMBER , PDSE.MANAGE_NUMBER , PDSE.ADD_DATE , PDSE.ADD_TIME , PDSE.ADD_USER_ID , PDSE.ACCEPT_FLAG , PDSE.MANAGER_ID , PDSE.MANAGE_DEPT , PDSE.DEC_FLAG , UPIM.ITEM_NAME , UPIM.ITEM_CODE , UPIM.ITEM_TYPE , UPIM.SEAL_WIDTH , UPIM.SEAL_HEIGHT , UPIM.ITEM_NO , SEAL.SEAL_USE_DEPT , SEAL.SEAL_MG_DEPT , SEAL.SEAL_MG_USER_ID , SEAL.SUBJECT , SEAL.SEAL_CATEGORY AS CATEGORY_CODE , CODE.TEXT1 AS CATEGORY_NAME
, #DB_OWNER#GETDEPTNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, SEAL.SEAL_MG_DEPT , '') AS DEPT_NAME , SEAL.SEAL_TYPE , #DB_OWNER#GETCODETEXT(${session.HOUSE_CODE}, 'SM003', NVL(SEAL.SEAL_TYPE, ''), ${session.LANGUAGE}) AS SEAL_TYPE_NAME , SEAL.SEAL_ID , MAND.RECE_USER_ID FROM SSIPD_SEAL PDSE INNER JOIN SSEAL SEAL ON SEAL.HOUSE_CODE = PDSE.HOUSE_CODE AND SEAL.COMPANY_CODE = PDSE.COMPANY_CODE AND SEAL.MANAGE_NUMBER = PDSE.MANAGE_NUMBER INNER JOIN SUPIM UPIM ON UPIM.HOUSE_CODE = SEAL.HOUSE_CODE AND UPIM.COMPANY_CODE = SEAL.COMPANY_CODE AND UPIM.ITEM_CODE = SEAL.SEAL_TYPE AND UPIM.DEL_FLAG = 'N' LEFT OUTER JOIN SMAND MAND ON MAND.HOUSE_CODE = PDSE.HOUSE_CODE AND MAND.COMPANY_CODE = PDSE.COMPANY_CODE AND MAND.GIVE_COMPANY_CODE = PDSE.COMPANY_CODE AND MAND.RECE_COMPANY_CODE = PDSE.COMPANY_CODE AND MAND.GIVE_USER_ID = PDSE.MANAGER_ID AND MAND.RECE_USER_ID = ${session.ID} AND ${current.DATE} BETWEEN MAND.START_DATE AND MAND.END_DATE LEFT OUTER JOIN SCODE CODE ON CODE.HOUSE_CODE = PDSE.HOUSE_CODE AND CODE.TYPE = 'SC001' AND CODE.CODE = SEAL.SEAL_CATEGORY AND CODE.LANGUAGE = ${session.LANGUAGE} WHERE PDSE.HOUSE_CODE = ${session.HOUSE_CODE} AND PDSE.SMR_NUMBER = ${SMR_NUMBER} AND PDSE.SMD_NUMBER = $S{SMD_NUMBER} AND PDSE.MANAGE_NUMBER = $S{MANAGE_NUMBER} AND PDSE.ACCEPT_FLAG = $S{ACCEPT_FLAG} AND PDSE.DEC_FLAG = $S{DEC_FLAG} AND PDSE.COMPANY_CODE = ${session.COMPANY_CODE}
, #DB_OWNER#GETDEPTNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, SEAL.SEAL_MG_DEPT , '') AS DEPT_NAME , SEAL.SEAL_TYPE , #DB_OWNER#GETCODETEXT(${session.HOUSE_CODE}, 'SM003', NVL(SEAL.SEAL_TYPE, ''), ${session.LANGUAGE}) AS SEAL_TYPE_NAME , SEAL.SEAL_ID , MAND.RECE_USER_ID FROM SSIPD_SEAL PDSE INNER JOIN SSEAL SEAL ON SEAL.HOUSE_CODE = PDSE.HOUSE_CODE AND SEAL.COMPANY_CODE = PDSE.COMPANY_CODE AND SEAL.MANAGE_NUMBER = PDSE.MANAGE_NUMBER INNER JOIN SUPIM UPIM ON UPIM.HOUSE_CODE = SEAL.HOUSE_CODE AND UPIM.COMPANY_CODE = SEAL.COMPANY_CODE AND UPIM.ITEM_CODE = SEAL.SEAL_TYPE LEFT OUTER JOIN SMAND MAND ON MAND.HOUSE_CODE = PDSE.HOUSE_CODE AND MAND.COMPANY_CODE = PDSE.COMPANY_CODE AND MAND.GIVE_COMPANY_CODE = PDSE.COMPANY_CODE AND MAND.RECE_COMPANY_CODE = PDSE.COMPANY_CODE AND MAND.GIVE_USER_ID = PDSE.MANAGER_ID AND MAND.RECE_USER_ID = ${session.ID} AND ${current.DATE} BETWEEN MAND.START_DATE AND MAND.END_DATE LEFT OUTER JOIN SCODE CODE ON CODE.HOUSE_CODE = PDSE.HOUSE_CODE AND CODE.TYPE = 'SC001' AND CODE.CODE = SEAL.SEAL_CATEGORY AND CODE.LANGUAGE = ${session.LANGUAGE} WHERE PDSE.HOUSE_CODE = ${session.HOUSE_CODE} AND PDSE.SMR_NUMBER = ${SMR_NUMBER} AND PDSE.SMD_NUMBER = $S{SMD_NUMBER} AND PDSE.MANAGE_NUMBER = $S{MANAGE_NUMBER} AND PDSE.ACCEPT_FLAG = $S{ACCEPT_FLAG} AND PDSE.DEC_FLAG = $S{DEC_FLAG} AND PDSE.COMPANY_CODE = ${session.COMPANY_CODE}
, #DB_OWNER#GETDEPTNAME(${session.HOUSE_CODE}, ${COMPANY_CODE}, SEAL.SEAL_MG_DEPT , '') AS DEPT_NAME , SEAL.SEAL_TYPE , #DB_OWNER#GETCODETEXT(${session.HOUSE_CODE}, 'SM003', NVL(SEAL.SEAL_TYPE, ''), ${session.LANGUAGE}) AS SEAL_TYPE_NAME , SEAL.SEAL_ID , MAND.RECE_USER_ID FROM SSIPD_SEAL PDSE INNER JOIN SSEAL SEAL ON SEAL.HOUSE_CODE = PDSE.HOUSE_CODE AND SEAL.COMPANY_CODE = PDSE.COMPANY_CODE AND SEAL.MANAGE_NUMBER = PDSE.MANAGE_NUMBER INNER JOIN SUPIM UPIM ON UPIM.HOUSE_CODE = SEAL.HOUSE_CODE AND UPIM.COMPANY_CODE = SEAL.COMPANY_CODE AND UPIM.ITEM_CODE = SEAL.SEAL_TYPE LEFT OUTER JOIN SMAND MAND ON MAND.HOUSE_CODE = PDSE.HOUSE_CODE AND MAND.COMPANY_CODE = PDSE.COMPANY_CODE AND MAND.GIVE_COMPANY_CODE = PDSE.COMPANY_CODE AND MAND.RECE_COMPANY_CODE = PDSE.COMPANY_CODE AND MAND.GIVE_USER_ID = PDSE.MANAGER_ID AND MAND.RECE_USER_ID = ${session.ID} AND ${current.DATE} BETWEEN MAND.START_DATE AND MAND.END_DATE LEFT OUTER JOIN SCODE CODE ON CODE.HOUSE_CODE = PDSE.HOUSE_CODE AND CODE.TYPE = 'SC001' AND CODE.CODE = SEAL.SEAL_CATEGORY AND CODE.LANGUAGE = ${session.LANGUAGE} WHERE PDSE.HOUSE_CODE = ${session.HOUSE_CODE} AND PDSE.SMR_NUMBER = ${SMR_NUMBER} AND PDSE.SMD_NUMBER = $S{SMD_NUMBER} AND PDSE.MANAGE_NUMBER = $S{MANAGE_NUMBER} AND PDSE.ACCEPT_FLAG = $S{ACCEPT_FLAG} AND PDSE.DEC_FLAG = $S{DEC_FLAG} AND PDSE.COMPANY_CODE = $S{COMPANY_CODE}


INSERT INTO SSIPD_SEAL (
	  HOUSE_CODE
	, COMPANY_CODE
	, SMR_NUMBER
	, SMD_NUMBER
	, MANAGE_NUMBER
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, DEL_FLAG
	, MANAGER_ID
	, MANAGE_DEPT
	, ACCEPT_FLAG
	, DEC_FLAG
) VALUES (
	  ${session.HOUSE_CODE  }
	, ${session.COMPANY_CODE}
	, ${SMR_NUMBER          }
	, ${SMD_NUMBER          }
	, ${MANAGE_NUMBER       }
	, ${current.DATE        }
	, ${current.TIME        }
	, ${session.ID          }
	, 'N'
	, ${SEAL_MG_USER_ID}
	, ${SEAL_MG_DEPT}
	, ${ACCEPT_FLAG}
	, ${DEC_FLAG}
)


UPDATE SSIPD_SEAL SET
	  CHANGE_DATE			= ${current.DATE}
