	, ACCEPT_FLAG			= NVL(${ACCEPT_FLAG}, ACCEPT_FLAG)
	, MANAGER_ID			= NVL($S{MANAGER_ID}, MANAGER_ID)
	, MANAGE_DEPT			= NVL($S{MANAGE_DEPT}, MANAGE_DEPT)
