SELECT SISD.HOUSE_CODE , SISD.COMPANY_CODE , SISD.SMR_NUMBER , SISD.SD_NUMBER , SISD.SMI_NUMBER , SISD.REAL_DOC_CHK , SISD.ADD_DATE , SISD.ADD_TIME , SISD.ADD_USER_ID , SISD.CHANGE_DATE , SISD.CHANGE_TIME , SISD.CHANGE_USER_ID , SISD.DEL_FLAG , SISD.DOC_TYPE , SISD.CONTENTS , SISD.COUNT , SISD.PRINT_COUNT , SISD.DOWN_COUNT , SISD.CERTIFICATE_NO , SISD.ATTACH_NO , (SELECT COUNT(1) FROM SFILE WHERE HOUSE_CODE = ${session.HOUSE_CODE} AND DOC_NO = SISD.SMR_NUMBER || '_' || SISD.SD_NUMBER AND NVL(DEL_FLAG, 'N') <> 'Y' ) AS ATTACH_CNT , A.DOC_SEQ AS ATTACH_SEQ , SISD.TEMPLATE_MAPPING_DATA , SRAD.TEMPLATE_FORM , SISD.PUBLISH_NO FROM SSISD SISD LEFT OUTER JOIN SFILE A ON A.HOUSE_CODE= SISD.HOUSE_CODE AND A.DOC_NO = SISD.ATTACH_NO INNER JOIN SSRAD SRAD ON SISD.HOUSE_CODE = SRAD.HOUSE_CODE AND SISD.COMPANY_CODE = SRAD.COMPANY_CODE AND SISD.SMI_NUMBER = SRAD.SMI_NUMBER WHERE SISD.HOUSE_CODE = ${session.HOUSE_CODE} AND SISD.SMR_NUMBER = ${SMR_NUMBER} AND SISD.SD_NUMBER = $S{SD_NUMBER} AND (A.DOC_SEQ IN ('','1') OR A.DOC_SEQ IS NULL)
AND SISD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SISD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SISD.COMPANY_CODE = $S{COMPANY_CODE}


INSERT INTO SSISD(
	  HOUSE_CODE
	, COMPANY_CODE
	, SMR_NUMBER
	, SD_NUMBER
	, SMI_NUMBER
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, DEL_FLAG
	, DOC_TYPE
	, CONTENTS
	, COUNT
	, REAL_DOC_CHK
	, ATTACH_NO
	, TEMPLATE_MAPPING_DATA
) VALUES (
	  ${session.HOUSE_CODE  }
	, ${session.COMPANY_CODE}
	, ${SMR_NUMBER          }
	, ${SD_NUMBER           }
	, ${SMI_NUMBER          }
	, ${current.DATE        }
	, ${current.TIME        }
	, ${session.ID          }
	, 'N'                   
	, ${DOC_TYPE            }
	, ${CONTENTS            }
	, ${COUNT               }
	, ${REAL_DOC_CHK		}
	, ${ATTACH_NO			}
	, ${TEMPLATE_MAPPING_DATA}
)


