	, CERTIFICATE_NO   = NVL(${CERTIFICATE_NO}  , CERTIFICATE_NO)
	, REAL_DOC_CHK	   = NVL(${REAL_DOC_CHK}  , REAL_DOC_CHK) 
	, SMI_NUMBER	   = NVL(${SMI_NUMBER}  , SMI_NUMBER)
