SELECT SRAD.HOUSE_CODE , SRAD.COMPANY_CODE , SRAD.SMI_NUMBER , SRAD.ADD_DATE , SRAD.ADD_TIME , SRAD.ADD_USER_ID , SRAD.SORT_SEQ , SRAD.CHANGE_DATE , SRAD.CHANGE_TIME , SRAD.CHANGE_USER_ID , SRAD.DEL_FLAG , SRAD.SUBJECT , SRAD.CONTENT , SRAD.DOC_TYPE , SRAD.START_DATE , SRAD.END_DATE , SRAD.ATTACH_NO , SRAD.USE_FLAG , SRAD.REAL_DOC_FLAG , SRAD.ELEC_DOC_FLAG , SRAD.TEMPLATE_FORM , #DB_OWNER#GETCODETEXT(${session.HOUSE_CODE}, 'SLM_261_1', NVL(SRAD.DOC_TYPE, ''), ${session.LANGUAGE}) AS DOC_TYPE_LOC , SRST.COUNT_STOCK FROM SSRAD SRAD LEFT OUTER JOIN (SELECT A.COUNT_STOCK , A.SMI_NUMBER , A.HOUSE_CODE , A.COMPANY_CODE FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY SMI_NUMBER ORDER BY ADD_DATE DESC, ADD_TIME DESC) RNUM , T.SMI_NUMBER , T.ADD_DATE , T.ADD_TIME , T.COUNT_STOCK , T.HOUSE_CODE , T.COMPANY_CODE FROM SSRST T ) A WHERE A.RNUM = 1) SRST ON SRAD.SMI_NUMBER = SRST.SMI_NUMBER AND SRAD.HOUSE_CODE = SRST.HOUSE_CODE AND SRAD.COMPANY_CODE = SRST.COMPANY_CODE WHERE SRAD.HOUSE_CODE = ${session.HOUSE_CODE} AND SRAD.SMI_NUMBER = $S{SMI_NUMBER} AND (SRAD.SMI_NUMBER LIKE '%' || $S{F_KEYWORD} || '%' OR SRAD.ADD_USER_ID LIKE '%' || $S{F_KEYWORD} || '%' OR SRAD.SUBJECT LIKE '%' || $S{F_KEYWORD} || '%' OR SRAD.CONTENT LIKE '%' || $S{F_KEYWORD} || '%' OR SRAD.DOC_TYPE LIKE '%' || $S{F_KEYWORD} || '%' ) AND SRAD.END_DATE >= $S{F_CALENDAR_FROM} AND SRAD.END_DATE <= $S{F_CALENDAR_TO} AND SRAD.DOC_TYPE = $S{REQ_DOC_TYPE} AND SRAD.START_DATE >= $S{REQ_DATE_FROM} AND SRAD.END_DATE <= $S{REQ_DATE_TO}
AND SRAD.USE_FLAG = '1'
AND SRAD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SRAD.COMPANY_CODE = ${session.COMPANY_CODE}
AND SRAD.COMPANY_CODE = $S{COMPANY_CODE} AND SRAD.COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})
ORDER BY SRAD.SORT_SEQ ASC


