SELECT COMPANY_CODE ,CONT_NO ,CONT_GL_SEQ ,SEQ ,ADD_DATE ,ADD_TIME ,USER_COMPANY_CODE ,USER_ID ,ACTION ,IP
,#DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, USER_ID, ${session.LANGUAGE}) AS USER_NAME ,#DB_OWNER#GETUSERDEPTNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, USER_ID, ${session.LANGUAGE}) AS USER_DEPT_NAME ,#DB_OWNER#GETCOMPANYNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, ${session.LANGUAGE}) AS USER_COMPANY_NAME FROM SPMGT WHERE HOUSE_CODE = ${session.HOUSE_CODE} AND COMPANY_CODE = ${session.COMPANY_CODE}
,#DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, USER_ID, ${session.LANGUAGE}) AS USER_NAME ,#DB_OWNER#GETUSERDEPTNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, USER_ID, ${session.LANGUAGE}) AS USER_DEPT_NAME ,#DB_OWNER#GETCOMPANYNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, ${session.LANGUAGE}) AS USER_COMPANY_NAME FROM SPMGT WHERE HOUSE_CODE = ${session.HOUSE_CODE} AND COMPANY_CODE = ${session.COMPANY_CODE}
,#DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, ${COMPANY_CODE}, USER_ID, ${session.LANGUAGE}) AS USER_NAME ,#DB_OWNER#GETUSERDEPTNAME(${session.HOUSE_CODE}, ${COMPANY_CODE}, USER_ID, ${session.LANGUAGE}) AS USER_DEPT_NAME ,#DB_OWNER#GETCOMPANYNAME(${session.HOUSE_CODE}, ${COMPANY_CODE}, ${session.LANGUAGE}) AS USER_COMPANY_NAME FROM SPMGT WHERE HOUSE_CODE = ${session.HOUSE_CODE} AND COMPANY_CODE = ${COMPANY_CODE}
AND CONT_NO = ${SMR_NUMBER} AND CONT_GL_SEQ = '1' ORDER BY SEQ


INSERT
  INTO SPMGT
     ( HOUSE_CODE       
      ,COMPANY_CODE     
      ,CONT_NO          
      ,CONT_GL_SEQ      
      ,SEQ              
      ,ADD_DATE         
      ,ADD_TIME         
      ,USER_COMPANY_CODE
      ,USER_ID          
      ,ACTION           
      ,IP
     )
VALUES
     ( ${session.HOUSE_CODE}       
      ,${session.COMPANY_CODE}     
      ,${SMR_NUMBER}        
      ,'1'      
      ,(SELECT COUNT(1) + 1
          FROM SPMGT InPMGT
         WHERE InPMGT.HOUSE_CODE   = ${session.HOUSE_CODE}
           AND InPMGT.COMPANY_CODE = ${session.COMPANY_CODE}
           AND InPMGT.CONT_NO      = ${SMR_NUMBER}
           AND InPMGT.CONT_GL_SEQ  = '1'
       )
      ,${current.DATE}         
      ,${current.TIME}         
      ,${session.COMPANY_CODE}
      ,${session.ID}
      ,${ACTION}           
      ,${IP}
     )


DELETE
  FROM SPMGT
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND CONT_NO      = ${SMR_NUMBER}
   AND CONT_GL_SEQ  = '1'

SELECT SIAD.HOUSE_CODE , SIAD.COMPANY_CODE , SIAD.SMR_NUMBER , SIAD.SMR_STATUS , SIAD.ADD_DATE , SIAD.ADD_TIME , SIAD.ADD_USER_ID , SIAD.CHANGE_DATE , SIAD.CHANGE_TIME , SIAD.CHANGE_USER_ID , SIAD.DEL_FLAG , SIAD.APPLY_TYPE , SIAD.SUBJECT , SIAD.RE_FLAG , SIAD.RE_DETAIL , SIAD.REQ_SEAL_USE_TYPE , SIAD.SUBMISSION_PLACE , SIAD.REMARK , SIAD.RCPT_TYPE , SIAD.RCPT_REMARK , SIAD.CONFIRM_DATE , SIAD.CONFIRM_TIME , SIAD.CONFIRM_USER_ID , SIAD.SUBMIT_TYPE , SIAD.SUBMIT_REMARK , SIAD.LEGAL_WATERMARK , UDGL.SUBJECT AS REQ_SEAL_USE_TYPE_TEXT
, #DB_OWNER#GETUSERDEPTNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, SIAD.ADD_USER_ID, ${session.LANGUAGE}) AS DEPT_NAME_LOC , #DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, SIAD.ADD_USER_ID, ${session.LANGUAGE}) as USER_NAME_LOC , #DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, SIAD.CONFIRM_USER_ID, ${session.LANGUAGE}) as CONFIRM_USER_NAME_LOC , ( SELECT COUNT(*) FROM SSIPD SIPD WHERE SIPD.HOUSE_CODE = SIAD.HOUSE_CODE AND SIPD.COMPANY_CODE = SIAD.COMPANY_CODE AND SIPD.SMR_NUMBER = SIAD.SMR_NUMBER AND #DB_OWNER#NVL(SIPD.DEL_FLAG, 'N') = 'N' ) AS DOC_CNT FROM SSIAD SIAD LEFT OUTER JOIN SUSMT ADD_USMT ON ADD_USMT.HOUSE_CODE = SIAD.HOUSE_CODE AND ADD_USMT.USER_ID = SIAD.ADD_USER_ID LEFT OUTER JOIN SUSMT CONFIRM_USMT ON CONFIRM_USMT.HOUSE_CODE = SIAD.HOUSE_CODE AND CONFIRM_USMT.USER_ID = SIAD.CONFIRM_USER_ID LEFT OUTER JOIN SUDGL UDGL ON UDGL.HOUSE_CODE = SIAD.HOUSE_CODE AND UDGL.COMPANY_CODE = SIAD.COMPANY_CODE AND UDGL.USE_NUMBER = SIAD.REQ_SEAL_USE_TYPE WHERE SIAD.HOUSE_CODE = ${session.HOUSE_CODE} AND SIAD.COMPANY_CODE = ${session.COMPANY_CODE}
, #DB_OWNER#GETUSERDEPTNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, SIAD.ADD_USER_ID, ${session.LANGUAGE}) AS DEPT_NAME_LOC , #DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, SIAD.ADD_USER_ID, ${session.LANGUAGE}) as USER_NAME_LOC , #DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, ${session.COMPANY_CODE}, SIAD.CONFIRM_USER_ID, ${session.LANGUAGE}) as CONFIRM_USER_NAME_LOC , ( SELECT COUNT(*) FROM SSIPD SIPD WHERE SIPD.HOUSE_CODE = SIAD.HOUSE_CODE AND SIPD.COMPANY_CODE = SIAD.COMPANY_CODE AND SIPD.SMR_NUMBER = SIAD.SMR_NUMBER AND #DB_OWNER#NVL(SIPD.DEL_FLAG, 'N') = 'N' ) AS DOC_CNT FROM SSIAD SIAD LEFT OUTER JOIN SUSMT ADD_USMT ON ADD_USMT.HOUSE_CODE = SIAD.HOUSE_CODE AND ADD_USMT.USER_ID = SIAD.ADD_USER_ID LEFT OUTER JOIN SUSMT CONFIRM_USMT ON CONFIRM_USMT.HOUSE_CODE = SIAD.HOUSE_CODE AND CONFIRM_USMT.USER_ID = SIAD.CONFIRM_USER_ID LEFT OUTER JOIN SUDGL UDGL ON UDGL.HOUSE_CODE = SIAD.HOUSE_CODE AND UDGL.COMPANY_CODE = SIAD.COMPANY_CODE AND UDGL.USE_NUMBER = SIAD.REQ_SEAL_USE_TYPE WHERE SIAD.HOUSE_CODE = ${session.HOUSE_CODE} AND SIAD.COMPANY_CODE = ${session.COMPANY_CODE}
, #DB_OWNER#GETUSERDEPTNAME(${session.HOUSE_CODE}, SIAD.COMPANY_CODE, SIAD.ADD_USER_ID, ${session.LANGUAGE}) AS DEPT_NAME_LOC , #DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, SIAD.COMPANY_CODE, SIAD.ADD_USER_ID, ${session.LANGUAGE}) as USER_NAME_LOC , #DB_OWNER#GETUSERNAME(${session.HOUSE_CODE}, SIAD.COMPANY_CODE, SIAD.CONFIRM_USER_ID, ${session.LANGUAGE}) as CONFIRM_USER_NAME_LOC , ( SELECT COUNT(*) FROM SSIPD SIPD WHERE SIPD.HOUSE_CODE = SIAD.HOUSE_CODE AND SIPD.COMPANY_CODE = SIAD.COMPANY_CODE AND SIPD.SMR_NUMBER = SIAD.SMR_NUMBER AND #DB_OWNER#NVL(SIPD.DEL_FLAG, 'N') = 'N' ) AS DOC_CNT FROM SSIAD SIAD LEFT OUTER JOIN SUSMT ADD_USMT ON ADD_USMT.HOUSE_CODE = SIAD.HOUSE_CODE AND ADD_USMT.USER_ID = SIAD.ADD_USER_ID LEFT OUTER JOIN SUSMT CONFIRM_USMT ON CONFIRM_USMT.HOUSE_CODE = SIAD.HOUSE_CODE AND CONFIRM_USMT.USER_ID = SIAD.CONFIRM_USER_ID LEFT OUTER JOIN SUDGL UDGL ON UDGL.HOUSE_CODE = SIAD.HOUSE_CODE AND UDGL.COMPANY_CODE = SIAD.COMPANY_CODE AND UDGL.USE_NUMBER = SIAD.REQ_SEAL_USE_TYPE WHERE SIAD.HOUSE_CODE = ${session.HOUSE_CODE} AND SIAD.COMPANY_CODE = $S{COMPANY_CODE} AND SIAD.COMPANY_CODE IN ($INS{AFFILIATED_COMPANY})
AND SIAD.SMR_NUMBER = $S{SMR_NUMBER} AND SIAD.ADD_USER_ID = $S{REQ_USER_ID} AND SIAD.APPLY_TYPE IN($INS{APPLY_TYPE}) AND SIAD.RE_FLAG IN($INS{RE_FLAG}) AND SIAD.SMR_STATUS IN($INS{SMR_STATUS}) AND (SIAD.SUBJECT LIKE '%' || $S{F_KEYWORD} || '%' OR SIAD.ADD_USER_ID LIKE '%' || $S{F_KEYWORD} || '%' OR SIAD.SUBMISSION_PLACE LIKE '%' || $S{F_KEYWORD} || '%' OR ADD_USMT.USER_NAME_LOC LIKE '%' || $S{F_KEYWORD} || '%' OR CONFIRM_USMT.USER_NAME_LOC LIKE '%' || $S{F_KEYWORD} || '%' ) AND SIAD.REQ_SEAL_USE_TYPE = $S{REQ_SEAL_USE_TYPE} AND SIAD.ADD_DATE >= $S{F_CALENDAR_FROM} AND SIAD.ADD_DATE <= $S{F_CALENDAR_TO} AND ( 1=1 AND SIAD.CONFIRM_USER_ID = $S{CONFIRM_USER_ID} OR (EXISTS( SELECT 1 FROM SSIPD_SEAL PDSE INNER JOIN SSEAL SEAL ON PDSE.HOUSE_CODE = SEAL.HOUSE_CODE AND PDSE.COMPANY_CODE = SEAL.COMPANY_CODE AND PDSE.MANAGE_NUMBER = SEAL.MANAGE_NUMBER WHERE PDSE.HOUSE_CODE = SIAD.HOUSE_CODE AND PDSE.COMPANY_CODE = SIAD.COMPANY_CODE AND PDSE.SMR_NUMBER = SIAD.SMR_NUMBER AND ( 1=1 AND PDSE.MANAGER_ID = $S{MANAGER_ID} OR SEAL.SUB_MG_USER_ID = $S{MANAGER_ID} ) ) ) ) ORDER BY SMR_NUMBER DESC


