INSERT INTO SAPPP (
       HOUSE_CODE
     , COMPANY_CODE
     , SMR_NUMBER
     , SEQ
     , RECENT
     , APP_STATUS
     , APPLY_FOR
     , POSTPROCESSED
     , ADD_DATE
     , ADD_TIME
     , CONFIRM_USER_ID
     , APP_COMMENT
     , APP_NO
     , APP_NO_SEQ
     , APP_LINE_SEQ
     , RE_FLAG
) VALUES(
       ${session.HOUSE_CODE}
     , ${COMPANY_CODE}
     , ${SMR_NUMBER}
     , CAST((CAST(NVL(
     			(SELECT PP.SEQ
				  FROM SAPPP PP
		 		 WHERE PP.HOUSE_CODE = ${session.HOUSE_CODE}
		   		   AND PP.COMPANY_CODE = ${COMPANY_CODE}
		   		   AND PP.SMR_NUMBER = ${SMR_NUMBER})
       , '0') as int) + 1) as varchar2(5) )
     , 'Y'
     , ${SMR_STATUS}
     , ${APPLY_FOR}
     , ${POSTPROCESSED}
     , ${CONFIRM_DATE}
     , ${CONFIRM_TIME}
     , ${CONFIRM_USER_ID}
     , ${APP_COMMENT}
     , ${APP_NO}
     , ${APP_NO_SEQ}
     , ${APP_LINE_SEQ}
     , ${RE_FLAG}
)


