 WHERE HOUSE_CODE IN ('000', ${HOUSE_CODE})
   AND SCREEN_ID = ${SCREEN_ID}
   AND LANGUAGE = ${LANGUAGE}
   AND CODE = ${CODE}
   AND NVL(CONTENTS, '') != ''
 ORDER BY HOUSE_CODE DESC


