SELECT CMGL.COMPANY_NAME_LOC AS COMPANY_NM , SEAL.MANAGE_NUMBER , SEAL.SUBJECT , CASE WHEN SEAL.SEAL_TYPE = 'C' THEN '법인인감' WHEN SEAL.SEAL_TYPE = 'U' THEN '사용인감' WHEN SEAL.SEAL_TYPE = 'E' THEN '서명인' ELSE 'Unknown' END AS SEAL_TYPE , SEAL.ADD_DATE AS REGIST_DATE , SEAL.ADD_TIME AS REGIST_TIME , SEAL.SEAL_ID , #DB_OWNER#GETUSERNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_USER_ID, ${session.LANGUAGE}) AS USER_NAME , #DB_OWNER#GETDEPTNAME(SEAL.HOUSE_CODE, SEAL.COMPANY_CODE, SEAL.SEAL_MG_DEPT , '') AS USER_DEPT , UDGL.SUBJECT AS UDGL_SUBJECT FROM SSEAL SEAL JOIN SUDGL UDGL ON UDGL.HOUSE_CODE = SEAL.HOUSE_CODE AND UDGL.COMPANY_CODE = SEAL.COMPANY_CODE JOIN SSUSE SUSE ON SUSE.HOUSE_CODE = SEAL.HOUSE_CODE AND SUSE.COMPANY_CODE =SEAL.COMPANY_CODE AND SUSE.USE_NUMBER = UDGL.USE_NUMBER AND SUSE.MANAGE_NUMBER = SEAL.MANAGE_NUMBER LEFT OUTER JOIN SCMGL CMGL ON CMGL.HOUSE_CODE = SEAL.HOUSE_CODE AND CMGL.COMPANY_CODE = SEAL.COMPANY_CODE AND CMGL.DEL_FLAG ='N' WHERE SEAL.HOUSE_CODE = ${session.HOUSE_CODE} AND SEAL.MANAGE_NUMBER = ${MANAGE_NUMBER} AND SEAL.DEL_FLAG ='N'
AND SEAL.COMPANY_CODE = ${session.COMPANY_CODE}
AND SEAL.COMPANY_CODE = ${session.COMPANY_CODE}
AND SEAL.COMPANY_CODE = ${COMPANY_CODE}


