SELECT SMR_NUMBER ,SEAL_TYPE ,RE_FLAG ,SMR_STATUS ,SUBJECT ,SEAL_USE_TYPE ,SUBMISSION_PLACE ,ADD_DATE ,ADD_USER_NAME ,ADD_USER_DEPT ,APP_DATE ,APP_USER_NAME ,APP_USER_DEPT ,DOC_SUBJECT ,ATTACH_NO FROM SSIAD_HISTORY WHERE HOUSE_CODE = ${session.HOUSE_CODE} AND COMPANY_CODE = ${session.COMPANY_CODE} AND SMR_NUMBER = $S{SMR_NUMBER} AND ( 1=1 AND SMR_STATUS = $S{F_STATUS} AND RE_FLAG IN($INS{F_RE_FLAG}) AND SEAL_USE_TYPE IN($INS{F_REQ_SEAL_USE_TYPE}) AND SEAL_TYPE IN($INS{F_APPLY_TYPE}) AND ( 1=1 AND SUBJECT LIKE '%' || $S{F_KEYWORD} || '%' OR SUBMISSION_PLACE LIKE '%' || $S{F_KEYWORD} || '%' ) )
AND ADD_DATE >= $S{F_CALENDAR_FROM} AND ADD_DATE <= $S{F_CALENDAR_TO}
AND APP_DATE >= $S{F_CALENDAR_FROM} AND APP_DATE <= $S{F_CALENDAR_TO}


