SELECT A.ADD_USER_DEPT, TO_CHAR(ADD_DATE, 'YY-MM-DD') AS MONTH, A.SMR_STATUS, CASE WHEN ${TABTYPE} IN ('CORP', 'USE') THEN A.RE_FLAG ELSE '' END AS RE_FLAG, COUNT(*) AS CNT FROM SSIAD A LEFT OUTER JOIN ( SELECT HOUSE_CODE, COMPANY_CODE, SMR_NUMBER FROM SSISD WHERE HOUSE_CODE = ${SESSION.HOUSE_CODE} AND COMPANY_CODE = ${SESSION.COMPANY_CODE} GROUP BY SMR_NUMBER ) B ON A.HOUSE_CODE = B.HOUSE_CODE AND A.COMPANY_CODE = B.COMPANY_CODE AND A.SMR_NUMBER = B.SMR_NUMBER WHERE A.HOUSE_CODE = ${SESSION.HOUSE_CODE} AND A.COMPANY_CODE = ${SESSION.COMPANY_CODE}
AND A.ADD_USER_DEPT = ${DEPT_CODE}
AND A.SMR_STATUS IN ('C','DC') AND A.ADD_DATE >= $S{F_CALENDAR_FROM} AND A.ADD_DATE <= $S{F_CALENDAR_TO} AND CASE WHEN ${TABTYPE} = 'CORPCERT' THEN (A.APPLY_TYPE = 'C' AND A.SMR_NUMBER = B.SMR_NUMBER) WHEN ${TABTYPE} = 'USECERT' THEN (A.APPLY_TYPE = 'U' AND A.SMR_NUMBER = B.SMR_NUMBER) WHEN ${TABTYPE} = 'CORP' THEN A.APPLY_TYPE = 'C' WHEN ${TABTYPE} = 'USE' THEN A.APPLY_TYPE = 'U' ELSE (A.APPLY_TYPE = 'D' AND A.SMR_NUMBER = B.SMR_NUMBER) END
GROUP BY TO_CHAR(A.ADD_DATE, 'YY-MM-DD'), A.SMR_STATUS, A.RE_FLAG
GROUP BY TO_CHAR(A.ADD_DATE, 'YY-MM-DD'), A.SMR_STATUS
ORDER BY TO_CHAR(A.ADD_DATE, 'YY-MM-DD') ASC


SELECT 
	*
FROM
	SSIAD
WHERE HOUSE_CODE 	= ${HOUSE_CODE}
  AND COMPANY_CODE 	= ${COMPANY_CODE}
  AND SMR_NUMBER 	= ${SMR_NUMBER}
  AND SMR_STATUS 	= 'DR'


		SELECT
			 HOUSE_CODE
			,COMPANY_CODE
			,CONT_NO
			,CONT_GL_SEQ
			,CONT_STATUS
			,CONT_SUBJECT
			,CATEGORY
			,INNER_MANAGER_NAME
			,EXT_EX_INNER_IRS_NO
			,EXT_EX_OUTER_IRS_NO
			,OUTER_COMPANY_NAME
			,OUTER_MANAGER_NAME
			,CONT_FROM
			,CONT_TO
			,CONT_DATE
			,CONT_METHOD
		FROM
			CONTRACT_HISTORY
		WHERE
			HOUSE_CODE = ${session.HOUSE_CODE}
			AND COMPANY_CODE = ${session.COMPANY_CODE}
			AND CONT_NO = $S{CONT_NO}
			AND CONT_GL_SEQ = $S{CONT_GL_SEQ}
			AND (
				1=1
				AND CONT_STATUS = $S{F_STATUS}
				AND CATEGORY = $S{F_CATEGORY}
				AND CONT_METHOD = $S{F_CONT_METHOD}
				AND (
					1=1
					AND CONT_SUBJECT LIKE '%' || $S{F_KEYWORD} || '%'
					OR INNER_MANAGER_NAME LIKE '%' || $S{F_KEYWORD} || '%'
					OR EXT_EX_INNER_IRS_NO LIKE '%' || $S{F_KEYWORD} || '%'
					OR EXT_EX_OUTER_IRS_NO LIKE '%' || $S{F_KEYWORD} || '%'
					OR OUTER_COMPANY_NAME LIKE '%' || $S{F_KEYWORD} || '%'
					OR OUTER_MANAGER_NAME LIKE '%' || $S{F_KEYWORD} || '%'
				)
			)



        	AND ADD_DATE	>= $S{F_CALENDAR_FROM}
			AND ADD_DATE	<= $S{F_CALENDAR_TO}




        	AND CONT_DATE	>= $S{F_CALENDAR_FROM}
			AND CONT_DATE	<= $S{F_CALENDAR_TO}




        	AND CONT_FROM	>= $S{F_CALENDAR_FROM}
			AND CONT_TO		<= $S{F_CALENDAR_TO}


INSERT INTO CONTRACT_HISTORY (
	 HOUSE_CODE
	,COMPANY_CODE
	,CONT_NO
	,CONT_GL_SEQ
	,CONT_STATUS
	,CONT_SUBJECT
	,CATEGORY
	,INNER_MANAGER_NAME
	,EXT_EX_INNER_IRS_NO
	,EXT_EX_OUTER_IRS_NO
	,OUTER_COMPANY_NAME
	,OUTER_MANAGER_NAME
	,CONT_FROM
	,CONT_TO
	,CONT_DATE
	,CONT_METHOD
) VALUES (
	 ${session.HOUSE_CODE}
	,${session.COMPANY_CODE}
	,${CONT_NO}
	,${CONT_GL_SEQ}
	,${CONT_STATUS}
	,${CONT_SUBJECT}
	,${CATEGORY}
	,${INNER_MANAGER_NAME}
	,${EXT_EX_INNER_IRS_NO}
	,${EXT_EX_OUTER_IRS_NO}
	,${OUTER_COMPANY_NAME}
	,${OUTER_MANAGER_NAME}
	,${CONT_FROM}
	,${CONT_TO}
	,${CONT_DATE}
	,${CONT_METHOD}
)


DELETE FROM CONTRACT_HISTORY
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
AND COMPANY_CODE = ${session.COMPANY_CODE}
AND CONT_NO = ${CONT_NO}
AND CONT_GL_SEQ = ${CONT_GL_SEQ}


