	AND SMR_NUMBER 		= ${SMR_NUMBER}


INSERT INTO SSRST (
	    HOUSE_CODE
		, COMPANY_CODE
		, SMI_NUMBER
		, SORT_SEQ
		, REASON
		, COUNT_DEPOSIT
		, COUNT_WITHDRAW
		, COUNT_STOCK
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, CHANGE_DATE
		, CHANGE_TIME
		, CHANGE_USER_ID
	) VALUES (
		  ${session.HOUSE_CODE  }
		, ${session.COMPANY_CODE}
		, ${SMI_NUMBER}
		, ${SORT_SEQ}
		, ${REASON}
		, #DB_OWNER#nvl(${COUNT_DEPOSIT}, 0)
		, #DB_OWNER#nvl(${COUNT_WITHDRAW}, 0)
		, #DB_OWNER#nvl(${COUNT_STOCK}, 0)
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
	)


UPDATE SSRST SET
	  CHANGE_DATE		= ${current.DATE}
	, CHANGE_TIME		= ${current.TIME}
	, CHANGE_USER_ID	= ${session.ID}
	, REASON			= #DB_OWNER#nvl(${REASON}, REASON)
	, COUNT_DEPOSIT		= #DB_OWNER#nvl(${COUNT_DEPOSIT}, 0)
	, COUNT_WITHDRAW	= #DB_OWNER#nvl(${COUNT_WITHDRAW}, 0)
	, COUNT_STOCK		= #DB_OWNER#nvl(${COUNT_STOCK}, 0)
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMI_NUMBER		= ${SMI_NUMBER}
AND SORT_SEQ        = ${SORT_SEQ}


DELETE 
FROM SSRST
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMI_NUMBER		= ${SMI_NUMBER}
AND SORT_SEQ        = ${SORT_SEQ}


		SELECT
			USMT.USER_ID
    	FROM
    		SUSMT USMT
		INNER JOIN SCODE CODE
			ON CODE.HOUSE_CODE = USMT.HOUSE_CODE
			AND CODE.TYPE = 'UX050'
			AND CODE.LANGUAGE = ${session.LANGUAGE}
			AND CODE.CODE = USMT.RESPONSIBILITY
    	WHERE
    		USMT.HOUSE_CODE = ${session.HOUSE_CODE}
    		AND USMT.COMPANY_CODE = ${session.COMPANY_CODE}
    		AND USMT.USER_ID = ${session.ID}
